-- Permissions for bills: the API had none to check, so any logged-in user could create, change or delete bills.
INSERT INTO OH_PERMISSIONS (P_ID_A, P_NAME, P_DESCRIPTION, P_ACTIVE, P_CREATED_BY, P_CREATED_DATE, P_LAST_MODIFIED_BY, P_LAST_MODIFIED_DATE) VALUES (172,'bills.create','',1,NULL,NULL,NULL,NULL);
INSERT INTO OH_PERMISSIONS (P_ID_A, P_NAME, P_DESCRIPTION, P_ACTIVE, P_CREATED_BY, P_CREATED_DATE, P_LAST_MODIFIED_BY, P_LAST_MODIFIED_DATE) VALUES (173,'bills.read','',1,NULL,NULL,NULL,NULL);
INSERT INTO OH_PERMISSIONS (P_ID_A, P_NAME, P_DESCRIPTION, P_ACTIVE, P_CREATED_BY, P_CREATED_DATE, P_LAST_MODIFIED_BY, P_LAST_MODIFIED_DATE) VALUES (174,'bills.update','',1,NULL,NULL,NULL,NULL);
INSERT INTO OH_PERMISSIONS (P_ID_A, P_NAME, P_DESCRIPTION, P_ACTIVE, P_CREATED_BY, P_CREATED_DATE, P_LAST_MODIFIED_BY, P_LAST_MODIFIED_DATE) VALUES (175,'bills.delete','',1,NULL,NULL,NULL,NULL);

-- Given to the admin group and to the groups that have billing in the desktop client (menu grants), so that nobody
-- loses access: reading with the bills browser or a new bill, creating with a new bill, updating (payments, closing)
-- with editing, deleting with deleting.
INSERT INTO OH_GROUPPERMISSION (GP_UG_ID_A, GP_P_ID_A, GP_ACTIVE, GP_CREATED_BY, GP_CREATED_DATE, GP_LAST_MODIFIED_BY, GP_LAST_MODIFIED_DATE)
SELECT DISTINCT GM_UG_ID_A, 173, 1, NULL, NULL, NULL, NULL FROM OH_GROUPMENU
WHERE GM_UG_ID_A = 'admin' OR (GM_ACTIVE = 1 AND GM_MNI_ID_A IN ('billsmanager', 'newbill', 'btnadmbill'));
INSERT INTO OH_GROUPPERMISSION (GP_UG_ID_A, GP_P_ID_A, GP_ACTIVE, GP_CREATED_BY, GP_CREATED_DATE, GP_LAST_MODIFIED_BY, GP_LAST_MODIFIED_DATE)
SELECT DISTINCT GM_UG_ID_A, 172, 1, NULL, NULL, NULL, NULL FROM OH_GROUPMENU
WHERE GM_UG_ID_A = 'admin' OR (GM_ACTIVE = 1 AND GM_MNI_ID_A IN ('newbill', 'btnbillnew', 'btnadmbill'));
INSERT INTO OH_GROUPPERMISSION (GP_UG_ID_A, GP_P_ID_A, GP_ACTIVE, GP_CREATED_BY, GP_CREATED_DATE, GP_LAST_MODIFIED_BY, GP_LAST_MODIFIED_DATE)
SELECT DISTINCT GM_UG_ID_A, 174, 1, NULL, NULL, NULL, NULL FROM OH_GROUPMENU
WHERE GM_UG_ID_A = 'admin' OR (GM_ACTIVE = 1 AND GM_MNI_ID_A = 'btnbilledit');
INSERT INTO OH_GROUPPERMISSION (GP_UG_ID_A, GP_P_ID_A, GP_ACTIVE, GP_CREATED_BY, GP_CREATED_DATE, GP_LAST_MODIFIED_BY, GP_LAST_MODIFIED_DATE)
SELECT DISTINCT GM_UG_ID_A, 175, 1, NULL, NULL, NULL, NULL FROM OH_GROUPMENU
WHERE GM_UG_ID_A = 'admin' OR (GM_ACTIVE = 1 AND GM_MNI_ID_A = 'btnbilldelete');
